import { useState } from "react";

const logoSrc = "data:image/png;base64,";

export default function UserTypeSelect({ onSelect }) {
  const handleSelect = (type) => {
    if (onSelect) {
      onSelect(type);
    } else {
      window.location.href = `/login?role=${type}`;
    }
  };

  return (
    <div>
      <div style={headerStyle}>
        <span style={brandStyle}>Attainment System</span>
        <div style={{ display: "flex", gap: 24 }}>
          <button style={linkBtn}>Login</button>
          <button style={linkBtn}>Sign up</button>
        </div>
      </div>

      <div style={mainStyle}>
        <img src={logoSrc} alt="Banasthali Vidyapith" style={logoStyle} />
        <p style={uniNameStyle}>Banasthali Vidyapith</p>

        <h1 style={headingStyle}>Choose user type</h1>

        <div style={cardsWrap}>
          <button style={cardBtn} onClick={() => handleSelect("admin")}>
            <div style={iconCircle}><UserIcon /></div>
            <span style={cardTitle}>Admin</span>
            <span style={cardSub}>Log in as an administrator</span>
          </button>

          <button style={cardBtn} onClick={() => handleSelect("teacher")}>
            <div style={iconCircle}><TeacherIcon /></div>
            <span style={cardTitle}>Teacher</span>
            <span style={cardSub}>Log in as a teacher</span>
          </button>
        </div>
      </div>
    </div>
  );
}

const headerStyle = { background: "#1c2b5e", padding: "18px 40px", display: "flex", justifyContent: "space-between", alignItems: "center" };
const brandStyle = { color: "#fff", fontSize: 22, fontWeight: 700 };
const linkBtn = { background: "none", border: "none", color: "#fff", fontSize: 16, cursor: "pointer" };
const mainStyle = { display: "flex", flexDirection: "column", alignItems: "center", padding: "40px 20px 80px", fontFamily: "sans-serif" };
const logoStyle = { width: 70, height: 70, marginTop: 20 };
const uniNameStyle = { fontFamily: "Georgia, serif", fontSize: 18, color: "#222", margin: "10px 0 30px" };
const headingStyle = { color: "#1c2b5e", fontSize: 30, fontWeight: 700, marginBottom: 40 };
const cardsWrap = { display: "flex", gap: 32, flexWrap: "wrap", justifyContent: "center" };
const cardBtn = { width: 220, background: "#2e3d7a", border: "none", borderRadius: 14, padding: "36px 20px", display: "flex", flexDirection: "column", alignItems: "center", cursor: "pointer" };
const iconCircle = { width: 64, height: 64, borderRadius: "50%", background: "rgba(255,255,255,0.18)", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 18 };
const cardTitle = { color: "#fff", fontSize: 20, fontWeight: 700, marginBottom: 8 };
const cardSub = { color: "#d6dbf0", fontSize: 14, textAlign: "center" };

function UserIcon() {
  return (
    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2">
      <circle cx="12" cy="8" r="4" />
      <path d="M4 20c0-4 3.5-7 8-7s8 3 8 7" />
    </svg>
  );
}

function TeacherIcon() {
  return (
    <svg width="30" height="28" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2">
      <circle cx="9" cy="8" r="3.2" />
      <path d="M2.5 20c0-3.4 2.9-6 6.5-6s6.5 2.6 6.5 6" />
      <circle cx="17.5" cy="7.5" r="2.3" />
      <path d="M15 13c2.8.2 5 2.4 5 5.3" />
    </svg>
  );
}
